/** STUDIO JOS 워드마크. 놓인 곳의 글자색을 따릅니다. */
export function Wordmark({
  id,
  className,
  title = "STUDIO JOS",
}: {
  /** 페이지 안에서 겹치지 않는 값 (마스크 id 로 씁니다) */
  id: string;
  className?: string;
  title?: string;
}) {
  const maskId = `wm-${id}`;
  return (
    <svg
      className={className}
      viewBox="0 0 320 33"
      role="img"
      aria-label={title}
      style={{ fill: "none", stroke: "none" }}
    >
      <defs>
        <mask id={maskId}>
          {/* 흰 판 위에 원본 패스를 검게 얹으면 글자만 남습니다 */}
          <rect width="320" height="33" fill="#fff" />
          <path d={WORDMARK_PATH} fill="#000" />
          {WORDMARK_EXTRA.map((d, i) => (
            <path key={i} d={d} fill="#000" />
          ))}
        </mask>
      </defs>
      <rect width="320" height="33" fill="currentColor" mask={`url(#${maskId})`} />
    </svg>
  );
}

