/** 조스 BI 심볼. 원본 아트보드는 150×80 이라 그만큼만 씁니다. */
export function SymbolMark({
  id,
  className,
  title = "Studio JOS",
}: {
  id: string;
  className?: string;
  title?: string;
}) {
  const maskId = `sym-${id}`;
  return (
    <svg
      className={className}
      viewBox="0 0 150 80"
      role="img"
      aria-label={title}
      style={{ fill: "none", stroke: "none" }}
    >
      <defs>
        <mask id={maskId}>
          <rect width="150" height="80" fill="#fff" />
          <path d={SYMBOL_PATH} fill="#000" />
        </mask>
      </defs>
      <rect width="150" height="80" fill="currentColor" mask={`url(#${maskId})`} />
    </svg>
  );
}
